insert into public.question_bank (teks_code, teks_item_id, subject, grade_num, course, difficulty, qtype, prompt, choices, answer_idx, explanation, source, status, gen_batch)
select distinct on (v.prompt) v.code, i.id, d.subject,
       case when i.grade_level = 'K' then 0 when i.grade_level ~ '^[0-9]+' then substring(i.grade_level from '^[0-9]+')::smallint end,
       case when i.grade_level is null then i.grade_course_title end,
       v.diff, 'mc', v.prompt, v.choices, v.ans, v.expl, v.src, 'checked', 'g7_math_v1'
from (values
('111.27.b.2',2,'Which set of numbers is a subset of the integers?','["whole numbers", "fractions between 0 and 1", "decimals only", "rational numbers"]'::jsonb,0,'Every whole number is also an integer.','original'),
('111.27.b.2',3,'Where would −3/5 be placed in a Venn diagram of whole numbers, integers and rational numbers?','["in the whole numbers", "in the rational numbers only", "outside every set", "in the integers"]'::jsonb,1,'It is a fraction of integers but is not an integer.','original'),
('111.27.b.2',3,'Which number is a rational number but NOT an integer?','["0", "12", "−4.25", "−4"]'::jsonb,2,'−4.25 = −17/4, which is not a whole amount.','original'),
('111.27.b.2',4,'Which set contains ONLY rational numbers that are integers?','["{1/2, 0, 9}", "{−6, 0, 9.1}", "{−6, 0.5, 9}", "{−6, 0, 9}"]'::jsonb,3,'Integers have no fraction or decimal part.','original'),
('111.27.b.2',4,'Why is 0 both a whole number and an integer?','["Whole numbers are part of the integers, and 0 is a whole number", "Because 0 is not a rational number", "Because 0 is a fraction only", "Because 0 is negative"]'::jsonb,0,'0 belongs to the whole numbers, which are a subset of the integers.','original'),
('111.27.b.2',3,'Which number is irrational-looking but actually rational?','["the non-repeating decimal 0.1010010001…", "0.25", "√2", "π"]'::jsonb,1,'0.25 = 1/4, a ratio of integers.','original'),
('111.27.b.2',3,'A terminating decimal like 0.375 is...','["a whole number", "not a rational number", "a rational number", "an integer"]'::jsonb,2,'0.375 = 375/1000 = 3/8.','original'),
('111.27.b.3.A',3,'What is −0.1 + 1.8?','["−1.7", "2.7", "−1.9", "1.7"]'::jsonb,3,'Add the decimals carefully with signs: 1.7.','original'),
('111.27.b.3.A',3,'What is −1.7 + 0.6?','["−1.1", "1.1", "−2.3", "−0.1"]'::jsonb,0,'Add the decimals carefully with signs: −1.1.','original'),
('111.27.b.3.A',3,'What is 1.4 + (−0.8)?','["−0.6", "0.6", "2.2", "1.6"]'::jsonb,1,'Add the decimals carefully with signs: 0.6.','original'),
('111.27.b.3.A',3,'What is −1.8 + 1.0?','["−2.8", "0.2", "−0.8", "0.8"]'::jsonb,2,'Add the decimals carefully with signs: −0.8.','original'),
('111.27.b.3.A',3,'What is −7 × (6)?','["42", "−13", "−1", "−42"]'::jsonb,3,'Different signs give a negative product: −42.','original'),
('111.27.b.3.A',3,'What is 7 × (11)?','["77", "−77", "−4", "18"]'::jsonb,0,'Same signs give a positive product: 77.','original'),
('111.27.b.3.A',3,'What is −11 × (−7)?','["−18", "77", "−4", "−77"]'::jsonb,1,'Same signs give a positive product: 77.','original'),
('111.27.b.3.A',3,'What is 2 × (−6)?','["12", "−4", "−12", "8"]'::jsonb,2,'Different signs give a negative product: −12.','original'),
('111.27.b.3.A',3,'What is −35 ÷ 7?','["5", "−42", "−4", "−5"]'::jsonb,3,'−35 ÷ 7 = −5.','original'),
('111.27.b.3.A',3,'What is −56 ÷ 7?','["−8", "8", "−63", "−7"]'::jsonb,0,'−56 ÷ 7 = −8.','original'),
('111.27.b.3.A',3,'What is 16 ÷ 2?','["−8", "8", "14", "9"]'::jsonb,1,'16 ÷ 2 = 8.','original'),
('111.27.b.3.A',4,'What is 5/4 + 1/2?','["3/4", "−7/4", "7/4", "5/8"]'::jsonb,2,'Use a common denominator; the sum is 7/4.','original'),
('111.27.b.3.A',4,'What is 5/2 + 5/6?','["25/12", "5/3", "−10/3", "10/3"]'::jsonb,3,'Use a common denominator; the sum is 10/3.','original'),
('111.27.b.3.A',4,'What is 2/3 + 5/8?','["31/24", "−31/24", "1/24", "5/12"]'::jsonb,0,'Use a common denominator; the sum is 31/24.','original'),
('111.27.b.3.A',4,'What is 5/2 + 2?','["1/2", "9/2", "−9/2", "5"]'::jsonb,1,'Use a common denominator; the sum is 9/2.','original'),
('111.27.b.3.A',3,'What is −3/4 + 1/4?','["1/2", "−3/16", "−1/2", "−1"]'::jsonb,2,'−3/4 + 1/4 = −2/4 = −1/2.','original'),
('111.27.b.3.A',3,'What is −2/3 × (−3/4)?','["2", "−1/2", "−9/12", "1/2"]'::jsonb,3,'Two negatives make a positive: 6/12 = 1/2.','original'),
('111.27.b.3.A',4,'What is −5/6 ÷ (−5/12)?','["2", "25/72", "1/2", "−2"]'::jsonb,0,'−5/6 × (−12/5) = 2.','original'),
('111.27.b.3.A',3,'What is −7.5 − (−2.5)?','["10", "−5", "−10", "5"]'::jsonb,1,'Subtracting a negative is adding: −7.5 + 2.5 = −5.','original'),
('111.27.b.3.B',3,'At 6 a.m. the temperature was −4°F. By noon it rose 15°F. What was the temperature at noon?','["−19°F", "−11°F", "11°F", "19°F"]'::jsonb,2,'−4 + 15 = 11.','original'),
('111.27.b.3.B',3,'A diver at −30 ft rises 12 ft. What is the diver''s new depth?','["18 ft", "−42 ft", "−360 ft", "−18 ft"]'::jsonb,3,'−30 + 12 = −18.','original'),
('111.27.b.3.B',4,'A bank account balance is −$25. A deposit of $60 is made. What is the new balance?','["$35", "−$35", "$85", "−$85"]'::jsonb,0,'−25 + 60 = 35.','original'),
('111.27.b.3.B',4,'A stock changes by −$1.50 each day for 4 days. What is the total change?','["$6.00", "−$6.00", "−$5.50", "−$0.38"]'::jsonb,1,'4 × (−1.50) = −6.00.','original'),
('111.27.b.3.B',4,'A recipe needs 3/4 cup of sugar per batch. How many cups for 2 1/2 batches?','["3 1/4 cups", "1 1/4 cups", "1 7/8 cups", "3 3/4 cups"]'::jsonb,2,'3/4 × 5/2 = 15/8 = 1 7/8.','original'),
('111.27.b.3.B',3,'Eli owes $45 and pays back $18. How would you write his new balance as an integer?','["−$63", "$63", "$27", "−$27"]'::jsonb,3,'−45 + 18 = −27.','original'),
('111.27.b.3.B',4,'The temperature drops 3°F every hour for 5 hours, starting at 2°F. What is the final temperature?','["−13°F", "7°F", "−15°F", "13°F"]'::jsonb,0,'2 + 5(−3) = −13.','original'),
('111.27.b.4.A',3,'A table shows x = 1, 2, 3, 4 and y = 3, 6, 9, 12. What is the constant rate of change?','["1", "3", "9", "12"]'::jsonb,1,'y increases by 3 each time x increases by 1.','original'),
('111.27.b.4.A',3,'A graph is a straight line through (0, 0) and (2, 10). What is the constant rate of change?','["1/5", "2", "5", "10"]'::jsonb,2,'10 ÷ 2 = 5.','original'),
('111.27.b.4.A',4,'A taxi charges $2.50 per mile. Which equation represents the cost c for m miles?','["c = m ÷ 2.5", "c = m + 2.5", "m = 2.5c", "c = 2.5m"]'::jsonb,3,'Cost is 2.5 times the miles.','original'),
('111.27.b.4.A',4,'Which table shows a constant rate of change?','["x: 1, 2, 3 and y: 4, 8, 12", "x: 1, 2, 3 and y: 9, 4, 1", "x: 1, 2, 3 and y: 4, 5, 7", "x: 1, 2, 3 and y: 2, 5, 11"]'::jsonb,0,'The y-values increase by 4 each time.','original'),
('111.27.b.4.A',4,'Which describes a graph of a constant rate of change?','["scattered points", "a straight line", "a curve that bends", "a vertical jump then flat"]'::jsonb,1,'Constant rate means a straight line.','original'),
('111.27.b.4.A',4,'Water drains from a tank at 6 gallons per minute. Which representation matches?','["g = 6 − m", "g = m + 6", "g = 6m", "g = 6 ÷ m"]'::jsonb,2,'Gallons are 6 times minutes.','original'),
('111.27.b.4.B',3,'A cyclist rides 9 miles in 4 hours. What is the unit rate in miles per hour?','["4/9", "13", "36", "2 1/4"]'::jsonb,3,'9 ÷ 4 = 2 1/4 miles per hour.','original'),
('111.27.b.4.B',3,'A cyclist rides 10 miles in 4 hours. What is the unit rate in miles per hour?','["2 1/2", "2/5", "40", "14"]'::jsonb,0,'10 ÷ 4 = 2 1/2 miles per hour.','original'),
('111.27.b.4.B',3,'A cyclist rides 18 miles in 8 hours. What is the unit rate in miles per hour?','["144", "2 1/4", "26", "4/9"]'::jsonb,1,'18 ÷ 8 = 2 1/4 miles per hour.','original'),
('111.27.b.4.B',3,'A cyclist rides 10 miles in 8 hours. What is the unit rate in miles per hour?','["80", "18", "1 1/4", "4/5"]'::jsonb,2,'10 ÷ 8 = 1 1/4 miles per hour.','original'),
('111.27.b.4.B',3,'A store sells 4 pounds of grapes for $10. What is the price per pound?','["$40", "$0.40", "$4.00", "$2.50"]'::jsonb,3,'10 ÷ 4 = 2.5.','original'),
('111.27.b.4.B',4,'Brand A: 12 ounces for $3.00. Brand B: 20 ounces for $4.40. Which has the lower unit price?','["Brand B at $0.22 per ounce", "They are equal", "Brand A at $0.22 per ounce", "Brand A at $0.25 per ounce"]'::jsonb,0,'A is 3.00/12 = 0.25; B is 4.40/20 = 0.22.','original'),
('111.27.b.4.B',4,'Mia types 135 words in 3 minutes. What is her rate in words per minute?','["405", "45", "0.022", "132"]'::jsonb,1,'135 ÷ 3 = 45.','original'),
('111.27.b.4.B',3,'A recipe uses 3/4 cup of milk for every 1/2 cup of flour. What is the unit rate of milk per cup of flour?','["1/2", "2/3", "1 1/2", "3/8"]'::jsonb,2,'3/4 ÷ 1/2 = 3/2.','original'),
('111.27.b.4.C',3,'A table shows x = 2, 4, 6 and y = 10, 20, 30. What is the constant of proportionality k = y/x?','["10", "2", "30", "5"]'::jsonb,3,'10 ÷ 2 = 5.','original'),
('111.27.b.4.C',3,'A proportional relationship has points (3, 12) and (5, 20). What is k?','["4", "9", "1/4", "15"]'::jsonb,0,'12 ÷ 3 = 4 and 20 ÷ 5 = 4.','original'),
('111.27.b.4.C',4,'A recipe uses 6 cups of flour for 4 loaves. What is the constant of proportionality for cups per loaf?','["2/3", "3/2", "24", "10"]'::jsonb,1,'6 ÷ 4 = 3/2.','original')
) as v(code, diff, prompt, choices, ans, expl, src)
join public.teks_items i on i.code = v.code and i.is_standard
join public.teks_documents d on d.id = i.document_id and d.subject = 'Mathematics' and d.language = 'en'
on conflict (fingerprint) do nothing;
