from (values
('111.27.b.4.C',4,'If y = 7x, what is the constant of proportionality?','["1/7", "y", "7", "x"]'::jsonb,2,'In y = kx, k = 7.','original'),
('111.27.b.4.C',4,'A graph shows a line through (0, 0) and (4, 6). What is k?','["24", "2/3", "10", "3/2"]'::jsonb,3,'6 ÷ 4 = 1.5.','original'),
('111.27.b.4.C',4,'A table has x = 1, 2, 3 and y = 5, 9, 13. Is it proportional?','["No, because y/x is not constant", "Yes, because y increases", "Yes, because k = 4", "No, because x increases"]'::jsonb,0,'5/1 = 5, 9/2 = 4.5, so the ratio changes.','original'),
('111.27.b.4.D',4,'A game price rises from $120 to $150. What is the percent increase?','["75%", "25%", "50%", "30%"]'::jsonb,1,'Change is 30; 30/120 = 25%.','original'),
('111.27.b.4.D',4,'A game price rises from $40 to $50. What is the percent increase?','["75%", "50%", "25%", "10%"]'::jsonb,2,'Change is 10; 10/40 = 25%.','original'),
('111.27.b.4.D',4,'A game price rises from $50 to $60. What is the percent increase?','["10%", "40%", "80%", "20%"]'::jsonb,3,'Change is 10; 10/50 = 20%.','original'),
('111.27.b.4.D',4,'A game price rises from $80 to $96. What is the percent increase?','["20%", "80%", "40%", "16%"]'::jsonb,0,'Change is 16; 16/80 = 20%.','original'),
('111.27.b.4.D',4,'A jacket price drops from $80 to $48. What is the percent decrease?','["32%", "40%", "60%", "50%"]'::jsonb,1,'Change is 32; 32/80 = 40%.','original'),
('111.27.b.4.D',4,'A jacket price drops from $50 to $40. What is the percent decrease?','["30%", "10%", "20%", "80%"]'::jsonb,2,'Change is 10; 10/50 = 20%.','original'),
('111.27.b.4.D',4,'A jacket price drops from $40 to $36. What is the percent decrease?','["20%", "4%", "90%", "10%"]'::jsonb,3,'Change is 4; 4/40 = 10%.','original'),
('111.27.b.4.D',4,'A jacket price drops from $80 to $72. What is the percent decrease?','["10%", "90%", "20%", "8%"]'::jsonb,0,'Change is 8; 8/80 = 10%.','original'),
