('111.27.b.4.D',4,'A $80 backpack is 20% off. What is the sale price?','["$16", "$74", "$64", "$96"]'::jsonb,2,'20% of 80 is 16; 80 − 16 = 64.','original'),
('111.27.b.4.D',4,'A $20 backpack is 20% off. What is the sale price?','["$4", "$24", "$26", "$16"]'::jsonb,3,'20% of 20 is 4; 20 − 4 = 16.','original'),
('111.27.b.4.D',4,'A $80 backpack is 25% off. What is the sale price?','["$60", "$100", "$70", "$20"]'::jsonb,0,'25% of 80 is 20; 80 − 20 = 60.','original'),
('111.27.b.4.D',4,'A price of $50 increases 10% and then decreases 10%. Is the final price $50?','["No, it is $45", "No, it is $49.50", "No, it is $55", "Yes, it is $50"]'::jsonb,1,'50 × 1.10 = 55, then 55 × 0.90 = 49.50.','original'),
('111.27.b.4.D',4,'A population grows from 400 to 500. What is the percent increase?','["125%", "100%", "25%", "20%"]'::jsonb,2,'100/400 = 25%.','original'),
('111.27.b.4.D',3,'What is 15% of 60?','["4", "90", "15", "9"]'::jsonb,3,'0.15 × 60 = 9.','original'),
('111.27.b.4.E',3,'About how many centimeters are in 10 inches? (1 inch is about 2.54 centimeters.)','["25.4 cm", "3.9 cm", "254 cm", "12.54 cm"]'::jsonb,0,'10 × 2.54 = 25.4.','original'),
('111.27.b.4.E',3,'About how many pounds are in 5 kilograms? (1 kg ≈ 2.2 lb)','["2.3 lb", "11 lb", "110 lb", "7.2 lb"]'::jsonb,1,'5 × 2.2 = 11.','original'),
('111.27.b.4.E',4,'A race is 5 kilometers. About how many miles is that? (1 mile ≈ 1.6 km)','["8 miles", "6.6 miles", "about 3.1 miles", "0.3 miles"]'::jsonb,2,'5 ÷ 1.6 ≈ 3.1.','original'),
('111.27.b.4.E',4,'About how many liters are in 3 gallons? (1 gallon ≈ 3.8 L)','["0.8 L", "6.8 L", "114 L", "11.4 L"]'::jsonb,3,'3 × 3.8 = 11.4.','original'),
('111.27.b.4.E',4,'Which proportion converts 50 miles to kilometers using 1 mi ≈ 1.6 km?','["1/1.6 = 50/x", "1/50 = 1.6/x", "1.6/1 = x/50 with x miles", "50/1.6 = x/1 with x pounds"]'::jsonb,0,'One mile is to 1.6 km as 50 miles is to x km: 1/1.6 = 50/x, giving 80 km.','original'),
