('111.27.b.6.A',4,'A spinner has colors R, G, B and a coin has H, T. How many outcomes?','["5", "8", "3", "6"]'::jsonb,3,'3 × 2 = 6.','original'),
('111.27.b.6.A',3,'A bag has a red, a blue and a green marble. Two are drawn one at a time without replacement. How many ordered outcomes?','["6", "3", "9", "4"]'::jsonb,0,'3 × 2 = 6.','original'),
('111.27.b.6.B',3,'Which tool could simulate a situation with a 1/6 chance?','["a ruler", "a six-sided die", "a coin", "a calendar"]'::jsonb,1,'A die has six equally likely faces.','original'),
